(*
【需求原文】
称重传感器长时间运行会出现零点漂移，需要在空秤时重新标定零点。

控制要求：
1. ZeroBtn 的上升沿把当前 RawWeight 采样为零点 ZeroOffset，同时清 DriftAlarm。
2. CompensatedWeight = (RawWeight - ZeroOffset) * 0.01（单位 kg，0.01 为标定系数），每个扫描周期更新。
3. 当 (RawWeight - ZeroOffset) 的绝对值超过 200（即 2 kg）时置 DriftAlarm = TRUE；回到 ±150 以内才复位（滞回）。
4. 上电时 ZeroOffset = 0，DriftAlarm = FALSE。
5. Status：16#0000 正常、16#8401 零点漂移、16#8402 采样值超量程（RawWeight 超出 -32768..32767 的可用段）。

扫描周期：20 ms。

待审语义冲突（保留，不宣称已解决）：
- 原文要求绝对偏差 > 200 才置位，形式规约 driftOut 使用 >= 200。
  本实现采用原文的严格大于边界。
- C2 要求报警时偏差始终 >= 200，与 K3/C6 在 150 < 绝对偏差 < 200
  区间保持报警的要求冲突。本实现保留原文滞回，不满足该区间的 C2。
- C10 要求初始扫描输出重量为零、无报警且零点为零；
  对任意非零输入，这与 C4 每扫描换算冲突；首扫描按钮为 TRUE 时，
  还与 K1 的上升沿标定冲突。本实现将给定初态作为执行扫描前的初值，
  首扫描即执行换算、边沿和报警逻辑，不强制零输出。
- RawWeight 为 INT，其可表示范围已是 -32768..32767，
  因而该接口无法传入题述超量程值，16#8402 分支不可由合法 INT 输入触发。
  不改变接口，也不将合法端点擅自视为故障。

初始化依赖本实例在上电时非保持初始化；部署不得将该实例配置为
断电保持并沿用旧状态。本源码未经过真实编译或逐周期测试验证。
CalibWeight 仅作显示输入，不参与换算。
*)

FUNCTION_BLOCK FB_S04
VAR_INPUT
    RawWeight : INT;
    ZeroBtn : BOOL;
    CalibWeight : REAL;
END_VAR
VAR_OUTPUT
    CompensatedWeight : REAL := 0.0;
    ZeroOffset : INT := 0;
    DriftAlarm : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ZeroBtnLast : BOOL := FALSE;
    ZeroRise : BOOL := FALSE;
    RawWide : DINT := 0;
    ZeroDelta : DINT := 0;
    AbsDelta : DINT := 0;
    SampleOutOfRange : BOOL := FALSE;
END_VAR

(* 在加减运算之前扩展类型，避免 INT 差值溢出。 *)
RawWide := INT_TO_DINT(RawWeight);
SampleOutOfRange :=
    (RawWide < DINT#-32768) OR (RawWide > DINT#32767);

ZeroRise := ZeroBtn AND NOT ZeroBtnLast;
ZeroBtnLast := ZeroBtn;

IF ZeroRise THEN
    ZeroOffset := RawWeight;
    DriftAlarm := FALSE;
END_IF;

ZeroDelta := RawWide - INT_TO_DINT(ZeroOffset);

IF ZeroDelta < DINT#0 THEN
    AbsDelta := -ZeroDelta;
ELSE
    AbsDelta := ZeroDelta;
END_IF;

CompensatedWeight := DINT_TO_REAL(ZeroDelta) * REAL#0.01;

(* 标定扫描清警；其余扫描执行置位、复位和中间区间保持。 *)
IF NOT ZeroRise THEN
    IF AbsDelta > DINT#200 THEN
        DriftAlarm := TRUE;
    ELSIF AbsDelta <= DINT#150 THEN
        DriftAlarm := FALSE;
    END_IF;
END_IF;

(* 状态优先级：采样超量程高于零点漂移。 *)
IF SampleOutOfRange THEN
    Status := WORD#16#8402;
ELSIF DriftAlarm THEN
    Status := WORD#16#8401;
ELSE
    Status := WORD#16#0000;
END_IF;

END_FUNCTION_BLOCK
